<script>
  import { delay, splitObject, toStyleString } from '@splendidlabz/utils'
  import { getParentElement } from '@splendidlabz/utils/dom'
  import { onMount } from 'svelte'
  import { mergeEntry, setEntry } from '../../../actions/sync.svelte.js'
  import { init } from '../../../utils'
  import { TRANSITION_OPT_KEYS } from '../../../utils/transitions.js'
  import DisclosureContent from '../Disclosure/DisclosureContent.svelte'
  import ModalContent from '../Modal/ModalContent.svelte'
  import PopoverContent from '../Popover/PopoverContent.svelte'
  import { getTBLRValues } from './drawer.js'

  let {
    class: klass = '',
    type: typeProp = 'modal',
    ref = $bindable(null),
    style = '',
    position,
    placement: placementProp,
    id,
    ...remainingProps
  } = $props()

  const split = $derived(splitObject(remainingProps, TRANSITION_OPT_KEYS))
  const transitionOpts = $derived(split.picked)
  const rest = $derived(split.omitted)

  const type = $derived(position === 'relative' ? 'disclosure' : typeProp)
  const placement = $derived(
    position === 'relative' ? placementProp || 'top' : placementProp,
  )
  const useReferenceBoundaries = $derived(type === 'popover')

  // Using DisclosureContent for relative position for nice slide effect.
  const disclosureContentProps = $derived.by(() => {
    if (position !== 'relative') return {}
    const TBLR = getTBLRValues({ placement, position })
    const styleString = toStyleString(TBLR) + style
    return {
      portal: false,
      style: styleString,
      placement,
      transition: 'slide',
      ...transitionOpts,
    }
  })

  let referenceNode = $state(null)
  init(() => setEntry(id, { type }))

  onMount(async _ => {
    await delay(0)
    mergeEntry(id, { drawer: ref })
    if (useReferenceBoundaries) referenceNode = getParentElement(ref)
  })

  const propsToPass = $derived({
    id,
    style,
    placement,
    ...rest,
    componentName: 'DrawerContent',
    class: `drawer-content ${klass}`,
  })
</script>

{#if type === 'modal'}
  <ModalContent bind:ref {...propsToPass} />
{:else if type === 'popover'}
  <PopoverContent
    {referenceNode}
    {useReferenceBoundaries}
    bind:ref
    {...propsToPass}
  />
{:else if type === 'disclosure'}
  <DisclosureContent bind:ref {...propsToPass} {...disclosureContentProps} />
{/if}
